	

In_pySegment .set 0
.macro py_Segment _Name, _Type, _az,_b,_c,_d,_e,_f

	_8th .set -1 ;Error out a channel using it if not-redefined.

	.if .blank(_Name)
		.error "Missing py_Segment _Name: py_Segment <_Name>, <_Type>, [_Type_args,]"

	.elseif .blank(_Type)
		.error "Missing py_Segment _Type: py_Segment <_Name>, <_Type>, [_Type_args,]"
	.endif

	;.xmatch if tpye is  Indicies, IndexRange, PageFit, Free, Defines

	.if Print_PC_Enabled

		.assert * = _Name, warning, "Given PC below is Inaccurate"
		Print_PC_as_Warning

		;.define pySegment_Name _Name

	.endif

	.if In_pySegment
		.error "Already in py_Segment"
	.else
		In_pySegment .set 1
	.endif


.endmacro



.macro py_Segment_End _Name

	.if .blank(_Name)
		.error "Missing py_Segment_End _Name: py_Segment <_Name>, <_Type>, [_Type_args,]"
	.endif

	;I can't think of a way to ca65 validate the same _Name was passed.

	.if Print_PC_Enabled
		Print_PC_as_Warning

	.endif

	.if In_pySegment
		In_pySegment .set 0
	.else
		.error "Not in a py_Segment"
	.endif

	;Validate matching Name?
.endmacro

In_pyIgnore .set 0
.macro py_Ignore

	.if In_pyIgnore
		.error "Already in py_Ignore"
	.else
		In_pyIgnore .set 1
	.endif

.endmacro ;Validate start / end pairs line up.

.macro py_Ignore_End

	.if In_pyIgnore
		In_pyIgnore .set 0
	.else
		.error "Not in a py_Ignore"
	.endif

.endmacro

.macro Force_Print_PC
	
	Print_PC_Assert_Unrolled

	.assert *=-1, warning, "    PC Above is Forced"
	.assert *=-1, warning, ""

.endmacro

.macro Print_PC_as_Warning
	.if Print_PC_Enabled

		Print_PC_Assert_Unrolled
		.assert *=-1, warning, "" ;See if one is blank

	.endif
.endmacro

